public void write()
{
    FormDataSource formDs = this;
    RetailPeriodicDiscountLine retailPeriodicDiscountLine = formDs.cursor();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        FormRun formRun = this.formRun();
        InventDim GUPInventDim = formRun.dataSource(formdatasourcestr(RetailPeriodicDiscount, GUPInventDim)).cursor();
        retailPeriodicDiscountLine.InventDimId = InventDim::findOrCreate(GUPInventDim).inventDimId;
    }

    next write();

    this.research(true);
}

public void initValue()
{
    FormDataSource formDs = this;
    RetailPeriodicDiscountLine retailPeriodicDiscountLine = formDs.cursor();

    next initValue();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        retailPeriodicDiscountLine.UnitAppliesToAll = NoYes::Yes;
        retailPeriodicDiscountLine.LinePricingGroupCode = GUPGroupAll::All;
    }
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && retailPeriodicDiscountLine is GUPFreeItemDiscountLine)
    {
        GUPFreeItemDiscountLine freeItemDiscountLine = retailPeriodicDiscountLine as GUPFreeItemDiscountLine;
        freeItemDiscountLine.FreeItemGroup = GUPFreeItemDiscountLine::nextFreeItemGroupNum(retailPeriodicDiscountLine.OfferId);
    }
}

public edit GUPPriceTermCalculateMethod editCalculationMethod(boolean set, RetailPeriodicDiscountLine discountLine, GUPPriceTermCalculateMethod calculateMethod)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance())
        && discountLine is RetailDiscountLineOffer)
    {
        RetailDiscountLineOffer discountLineOffer = discountLine;

        if (set)
        {
            if (calculateMethod == GUPPriceTermCalculateMethod::FixedAmount)
            {
                discountLineOffer.DiscountMethod = RetailDiscountOfferLineDiscMethodBase::AmountOff;
                discountLineOffer.DiscPct = 0;
            }
            else if (calculateMethod == GUPPriceTermCalculateMethod::Percent)
            {
                discountLineOffer.DiscountMethod = RetailDiscountOfferLineDiscMethodBase::PercentOff;
                discountLineOffer.DiscAmount= 0;
            }
        }
        else
        {
            if (discountLineOffer.DiscountMethod == RetailDiscountOfferLineDiscMethodBase::AmountOff)
            {
                calculateMethod = GUPPriceTermCalculateMethod::FixedAmount;
            }
            else if (discountLineOffer.DiscountMethod == RetailDiscountOfferLineDiscMethodBase::PercentOff)
            {
                calculateMethod = GUPPriceTermCalculateMethod::Percent;
            }
        }

        element.updateDiscountOfferLineView();
    }

    return calculateMethod;
}

public void executeQuery()
{
    next executeQuery();

    FormRun formRun = this.formRun();
    FormDataSource formDs = this;
    boolean allowAddEditFreeItemLine = false;

    FormControl freeItemLineButtonGroup = formRun.design().controlName(formControlStr(RetailPeriodicDiscount, FreeItemLinesBasicButtonGroup));
    FormControl freeItemLinesAddButton = formRun.design().controlName(formControlStr(RetailPeriodicDiscount, FreeItemLinesAddButton));
    FormControl freeItemLinesRemoveButton = formRun.design().controlName(formControlStr(RetailPeriodicDiscount, FreeItemLinesRemoveButton));

    RetailPeriodicDiscountLine retailPeriodicDiscountLine = formDs.cursor();        
    if (retailPeriodicDiscountLine)
    {
        allowAddEditFreeItemLine = true;
    }

    freeItemLineButtonGroup.enabled(allowAddEditFreeItemLine);
    freeItemLinesAddButton.enabled(allowAddEditFreeItemLine);
    freeItemLinesRemoveButton.enabled(allowAddEditFreeItemLine);
}

public int active()
{
    FormDataSource formDs = this;
    RetailPeriodicDiscountLine retailPeriodicDiscountLine = formDs.cursor();
    RetailPeriodicDiscount periodicDiscount = RetailPeriodicDiscount::findByOfferId(retailPeriodicDiscountLine.OfferId);

    int ret = next active();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        FormRun formRun = this.formRun();
        FormControl postingTab = formRun.design().controlName(formControlStr(RetailPeriodicDiscount, DiscountPostingTabPage));
        FormControl claimGrid = formRun.design().controlName(formControlStr(RetailPeriodicDiscount, ClaimDistributionGrid));
        FormControl allocationGrid = formRun.design().controlName(formControlStr(RetailPeriodicDiscount, DiscountAllocationGrid));
        FormControl freeItemLineGrid = formRun.design().controlName(formControlStr(RetailPeriodicDiscount, FreeItemLinesGrid));

        QueryBuildDataSource claimQbds = claimGrid.dataSourceObject().queryBuildDataSource();
        QueryBuildDataSource allocationQbds = allocationGrid.dataSourceObject().queryBuildDataSource();
        claimQbds.clearRanges();
        allocationQbds.clearRanges();

        boolean showPostingTab = false;
        boolean postingProfilePerDiscountLine = false;

        if (periodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::DiscountOffer ||
                periodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::DiscountOfferLineQuantityLimit)
        {
            RetailDiscountLineOffer retailDiscountLineOffer = retailPeriodicDiscountLine as RetailDiscountLineOffer;
            if (retailDiscountLineOffer.discountMethod != RetailDiscountOfferLineDiscMethodBase::Price
                    && periodicDiscount.PeriodicDiscountType != RetailDiscountOfferTypeBase::Promotion)
            {
                showPostingTab = true;
                postingProfilePerDiscountLine = true;
            }
        }

        if (postingProfilePerDiscountLine)
        {
            claimQbds.addRange(fieldNum(GUPPeriodicDiscountClaimDistribution, LineNum)).value(queryValue(retailPeriodicDiscountLine.LineNum));
            allocationQbds.addRange(fieldNum(GUPPeriodicDiscountAllocation, LineNum)).value(queryValue(retailPeriodicDiscountLine.LineNum));
            claimQbds.addRange(fieldNum(GUPPeriodicDiscountClaimDistribution, PostingSetupLevel)).value(queryValue(GUPDiscountPostingSetupLevel::Line));
            allocationQbds.addRange(fieldNum(GUPPeriodicDiscountAllocation, PostingSetupLevel)).value(queryValue(GUPDiscountPostingSetupLevel::Line));
        }

        claimGrid.dataSourceObject().executeQuery();
        allocationGrid.dataSourceObject().executeQuery();

        postingTab.visible(showPostingTab);
    }

    return ret;
}
